func TestColdPathRedirectAllReplicasFail(t *testing.T) {
	t.Parallel()
	fail1 := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "replica 1 unavailable", http.StatusServiceUnavailable)
	}))
	defer fail1.Close()
	fail2 := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		http.Error(w, "replica 2 unavailable", http.StatusServiceUnavailable)
	}))
	defer fail2.Close()

	entry := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("X-Entire-Replicas", buildReplicasHeader(fail1.URL, fail2.URL))
		http.Redirect(w, r, "http://example.invalid"+r.URL.RequestURI(), http.StatusTemporaryRedirect)
	}))
	defer entry.Close()

	p := proxyWithClient(nil, "/et/alice/repo", entry.URL, "127.0.0.1", entry.Client())

	_, err := p.InfoRefs(context.Background(), "git-upload-pack")
	require.Error(t, err)
	assert.Contains(t, err.Error(), "all 2 nodes failed")
	assert.Contains(t, err.Error(), "after entry-domain redirect")
}

